package app.veyra;
import android.app.*;import android.content.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
final class UpdatePrompt {
 static void show(Activity a,AppUpdates.Release release){Dialog d=new Dialog(a);LinearLayout root=Ui.column(a);root.setPadding(Ui.dp(a,24),Ui.dp(a,24),Ui.dp(a,24),Ui.dp(a,20));root.addView(Ui.text(a,"A new chapter.",28,Ui.INK));root.addView(Ui.text(a,"Velixio "+release.version+" · "+(release.size>0?StorageTools.format(release.size):"Size shown before download"),14,Ui.ACCENT));TextView notes=Ui.text(a,release.notes.isEmpty()?"An updated version is ready to download.":release.notes,15,Ui.INK);ScrollView scroll=new ScrollView(a);scroll.addView(notes);root.addView(scroll,new LinearLayout.LayoutParams(-1,Ui.dp(a,180)));Button update=Ui.primary(a,"Update");update.setOnClickListener(v->{d.dismiss();a.startActivity(new Intent(a,UpdatesActivity.class));});root.addView(update);Button later=Ui.quiet(a,"Remind me tomorrow");later.setOnClickListener(v->d.dismiss());root.addView(later);d.setContentView(root);d.setOnDismissListener(v->a.getSharedPreferences("update-settings",0).edit().putLong("snoozeUntil",System.currentTimeMillis()+24*60*60*1000L).apply());d.show();if(d.getWindow()!=null){GradientDrawable bg=new GradientDrawable();bg.setColor(Ui.BG);bg.setCornerRadius(Ui.dp(a,24));root.setBackground(bg);d.getWindow().setBackgroundDrawable(new ColorDrawable(android.graphics.Color.TRANSPARENT));d.getWindow().setLayout(Math.min(a.getResources().getDisplayMetrics().widthPixels-Ui.dp(a,32),Ui.dp(a,560)),-2);}}
}
